/**
 * Richiesta non valida
 */
export type BadRequestResponse = ErrorResponse;

/**
 * Conflitto con lo stato corrente della risorsa
 */
export type ConflictResponse = ErrorResponse;

/**
 * Login richiesto
 */
export type UnauthorizedResponse = ErrorResponse;

/**
 * Risorsa non accessibile all'utente corrente
 */
export type ForbiddenResponse = ErrorResponse;

/**
 * Risorsa non trovata
 */
export type NotFoundResponse = ErrorResponse;

/**
 * Servizio esterno non raggiungibile
 */
export type BadGatewayResponse = ErrorResponse;

/**
 * Corpo della richiesta troppo grande
 */
export type PayloadTooLargeResponse = ErrorResponse;

